/**
 * Where uploaded images are kept. The upload service talks only to this
 * interface, so moving from local disk to S3 means adding an implementation,
 * not changing the service. Keys are generated by the server
 * (`<uuid>.<ext>`); a user-supplied name never reaches storage.
 */
export type ImageStore = {
  /** Stores the bytes under a new key; fails if the key already exists. */
  put: (key: string, bytes: Buffer, contentType: string) => Promise<void>;
  /** Removes a stored image; one that is already gone is not an error. */
  remove: (key: string) => Promise<void>;
  /** The URL the browser loads the image from. */
  publicUrl: (key: string) => string;
};
